const IDX = { en: 0, ms: 1, zh: 2, ta: 3, km: 4 };
const TABLE = {};
ROWS.forEach((r) => { TABLE[r[0]] = r; });

const KEY = 'qd_lang';
function read() {
  try { const v = localStorage.getItem(KEY); if (v && IDX[v] !== undefined) return v; } catch (e) { /* ignore */ }
  return 'en';
}
let current = read();

export const getLang = () => current;
export function setLang(l) {
  if (IDX[l] === undefined) return;
  current = l;
  try { localStorage.setItem(KEY, l); } catch (e) { /* ignore */ }
  try { document.documentElement.lang = l; } catch (e) { /* ignore */ }
}

export function t(key, vars) {
  const row = TABLE[key];
  let s = row && row[IDX[current]] ? row[IDX[current]] : key;
  if (vars) Object.keys(vars).forEach((k) => { s = s.split(`{${k}}`).join(vars[k]); });
  return s;
}

export const dayName = (i) => DAYS[i][IDX[current]] || DAYS[i][0];
export const monthName = (i) => MONTHS[i][IDX[current]] || MONTHS[i][0];
